#!/usr/bin/env python3
"""Exact replay of two classical lower-bound rows of the 9a page (teorth/optimizationproblems, main 87b4ebb):

  [PS2018]  Theta(C_7) >= 367^(1/5) ~ 3.2578: the 367 words listed in the appendix of Polak and Schrijver
            (arXiv 1808.07438v2) form an independent set in the strong power C_7^5;
  [MO2017]  Theta(C_7) >= 350^(1/5) ~ 3.2271: the code of Mathew and Ostergard (arXiv 1504.01472v1, appendix,
            "G(5,7) >= 350"), the union of the orbits of its 50 representatives under the group generated by the
            value permutations i -> i + b_k (mod 7), b = (0, 1, 1, 5, 1) (a = 1, identity on coordinates, order 7).

Two words of Z_7^5 are adjacent in C_7^5 (strong product) when they differ and every coordinate differs by 0 or +-1
mod 7.  Independence is checked by two routes that share no code: every pair (some coordinate differs by 2, 3, 4 or
5 mod 7), and, for every word, all 3^5 - 1 = 242 neighbours looked up in the set.  Theta(C_7) >= alpha(C_7^5)^(1/5)
(supermultiplicativity of the independence number under strong products) gives the bound; the printed 4-decimal
values (truncations, so valid lower bounds) are compared by exact integer powers.  Anchor: the 367 words against the R367.txt file used in our [Gao2026]
replay (gao2026/R367.txt), when present.
usage: python3 -I ps_mo_check.py CERTS_ROOT [--controls]
"""
import itertools
import os
import re
import sys

ROOT = sys.argv[1] if len(sys.argv) > 1 and not sys.argv[1].startswith("--") else "certs"
CONTROLS = "--controls" in sys.argv
OFFS = [o for o in itertools.product((-1, 0, 1), repeat=5) if any(o)]


def need(cond, msg):
    if not cond:
        raise AssertionError(msg)


def ps_words(path):
    text = open(path, encoding="utf-8").read()
    i = text.index("Appendix: explicit code")
    j = text.index("\\end{samepage}", i)
    words = re.findall(r"\b([0-6]{5})\b", text[i:j])
    return [tuple(int(c) for c in w) for w in words]


def mo_code(path):
    text = open(path, encoding="utf-8").read()
    i = text.index("\\subsection*{$G(5,7)\\geq 350$:}")
    j = text.index("\\subsection*", i + 10)
    part = text[i:j]
    gen = tuple(int(x) for x in re.search(r"Generator: \(([^)]*)\)", part).group(1).split(","))
    order = int(re.search(r"Group order: (\d+)", part).group(1))
    reps = [tuple(int(x) for x in r.split(",")) for r in re.findall(r"\(([0-9, ]+)\)", part.split("Orbit representatives:")[1])]
    code = set()
    for r in reps:
        for t in range(7):
            code.add(tuple((r[k] + t * gen[k]) % 7 for k in range(5)))
    return gen, order, reps, code


def adjacent(u, v):
    return u != v and all((a - b) % 7 in (0, 1, 6) for a, b in zip(u, v))


def independent_pairs(words):
    for x, y in itertools.combinations(words, 2):
        if x == y or adjacent(x, y):
            return False, (x, y)
    return True, None


def independent_nbhd(words):
    s = set(words)
    if len(s) != len(words):
        return False, "repeated word"
    for w in words:
        for o in OFFS:
            v = tuple((a + b) % 7 for a, b in zip(w, o))
            if v in s:
                return False, (w, v)
    return True, None


def trunc_4(n, printed):
    """printed (an integer p for p/10^4) is n^(1/5) truncated to four decimals: p^5 <= n 10^20 < (p + 1)^5."""
    return printed ** 5 <= n * 10 ** 20 < (printed + 1) ** 5


def judge(label, words, printed):
    a, why_a = independent_pairs(words)
    b, why_b = independent_nbhd(words)
    need(a == b, f"{label}: the two routes disagree ({why_a}, {why_b})")
    n = len(set(words))
    r = trunc_4(n, printed)
    return a, n, r, why_a or why_b


def main():
    ok = True
    ps = ps_words(f"{ROOT}/ps2018/c7_367_rev2.tex")
    ind, n, r, why = judge("[PS2018]", ps, 32578)
    good = ind and n == 367 and len(ps) == 367 and r
    ok &= good
    print(f"[PS2018]: {len(ps)} words read from the appendix, {n} distinct, every symbol in 0..6; independent in "
          f"C_7^5 by both routes: {ind}{'' if ind else f' (first conflict {why})'}; 367^(1/5) = {367 ** 0.2:.10f}...")
    gp = f"{ROOT}/gao2026/R367.txt"
    if os.path.exists(gp):
        r367 = {tuple(int(x) for x in line.split()) for line in open(gp) if line.strip()}
        print(f"  anchor: the same 367 words as gao2026/R367.txt (used in our [Gao2026] replay): {r367 == set(ps)}")
    print(f"RESULT [PS2018]: alpha(C_7^5) >= 367, so Theta(C_7) >= 367^(1/5); the printed ~3.2578 is its truncation to four "
          f"decimals: {'HOLDS' if good else 'FAILS'}")
    gen, order, reps, code = mo_code(f"{ROOT}/mo2017/arxiv.tex")
    words = sorted(code)
    ind, n, r, why = judge("[MO2017]", words, 32271)
    good = ind and n == 350 and len(reps) == 50 and order == 7 and r
    ok &= good
    print(f"[MO2017]: generator b = {gen}, group order {order}; {len(reps)} orbit representatives, orbits of size 7 "
          f"give {n} distinct words; independent in C_7^5 by both routes: {ind}"
          f"{'' if ind else f' (first conflict {why})'}; 350^(1/5) = {350 ** 0.2:.10f}...")
    print(f"RESULT [MO2017]: alpha(C_7^5) >= 350, so Theta(C_7) >= 350^(1/5); the printed ~3.2271 is its truncation to four "
          f"decimals: {'HOLDS' if good else 'FAILS'}")
    if CONTROLS:
        print("red controls (each must be refused or fail):")
        res = []
        w0 = ps[0]
        nb = ((w0[0] + 1) % 7,) + w0[1:]          # a neighbour of the first word, added to the set
        res.append(("[PS2018] plus a neighbour of its first word", nb not in ps and not judge("c1", ps + [nb], 32578)[0]))
        res.append(("[PS2018] a repeated word", not independent_nbhd(ps + [ps[5]])[0]))
        res.append(("[PS2018] printed 3.2579", not trunc_4(367, 32579)))
        g2 = (0, 1, 1, 5, 2)
        code2 = set()
        for rr in reps:
            for t in range(7):
                code2.add(tuple((rr[k] + t * g2[k]) % 7 for k in range(5)))
        res.append(("[MO2017] generator (0,1,1,5,2)", not judge("c4", sorted(code2), 32271)[0] or len(code2) != 350))
        res.append(("[MO2017] printed 3.2272", not trunc_4(350, 32272)))
        for label, rr in res:
            print(f"  {label}: {'refused, as expected' if rr else 'NOT REFUSED'}")
        ok &= all(rr for _, rr in res)
        print("controls all as expected" if all(rr for _, rr in res) else "CONTROLS FAILED")
    sys.exit(0 if ok else 1)


if __name__ == "__main__":
    main()
